import { test } from 'node:test';
import assert from 'node:assert/strict';
import { situacaoDasPromessas } from './solution.mjs';

function depois(ms, valor) {
  return new Promise((resolve) => setTimeout(resolve, ms, valor));
}

function falha(ms, motivo) {
  return new Promise((_, reject) => setTimeout(reject, ms, new Error(motivo)));
}

test('separa resolvidas de rejeitadas, na ordem da lista', async () => {
  const s = await situacaoDasPromessas([
    depois(2, 'preco'),
    falha(4, 'estoque fora do ar'),
    depois(6, 'frete'),
  ]);
  assert.deepEqual(s.resolvidas, ['preco', 'frete']);
  assert.equal(s.rejeitadas.length, 1);
  assert.match(s.rejeitadas[0].message, /estoque fora do ar/);
});

test('todas resolvem: rejeitadas fica vazia', async () => {
  const s = await situacaoDasPromessas([depois(2, 'a'), depois(4, 'b')]);
  assert.deepEqual(s, { resolvidas: ['a', 'b'], rejeitadas: [] });
});

test('todas rejeitam: resolvidas fica vazia', async () => {
  const s = await situacaoDasPromessas([falha(2, 'x'), falha(3, 'y')]);
  assert.deepEqual(s.resolvidas, []);
  assert.equal(s.rejeitadas.length, 2);
});

test('lista vazia devolve as duas listas vazias', async () => {
  assert.deepEqual(await situacaoDasPromessas([]), { resolvidas: [], rejeitadas: [] });
});

solutionCode:
export async function situacaoDasPromessas(promessas) {
  const resultados = await Promise.allSettled(promessas);
  const resolvidas = [];
  const rejeitadas = [];
  for (const r of resultados) {
    if (r.status === 'fulfilled') {
      resolvidas.push(r.value);
    } else {
      rejeitadas.push(r.reason);
    }
  }
  return { resolvidas, rejeitadas };
}
